#include "robotblocks_runtime.h"

struct servos_canal { bool activo; };
inline void servos_mover(servos_canal& servo, int pin, float angulo, const char* bloque);
inline void servos_mover(servos_canal& servo, int pin, float angulo, const char* bloque) {
    if (!servo.activo) {
        if (!ledcAttach(pin, 50, 14)) { rb_fail(bloque, RB_ERROR_TEXT("No se pudo activar el servo")); return; }
        servo.activo = true;
    }
    angulo = fmaxf(0, fminf(180, rb_finite(angulo, bloque)));
    int pulso = int(500 + angulo * 2000 / 180);
    ledcWrite(pin, uint32_t(pulso) * 16383UL / 20000UL);
}
static servos_canal servo_4 = {};

static void proceso_1() {
    static RbProcessState s;
    PT_BEGIN(s);
    while (true) {
        servos_mover(servo_4, 4, 0, "basico-465");
        if (rb_failed) return;
        PT_SLEEP(s, 500);
        servos_mover(servo_4, 4, 90, "basico-469");
        if (rb_failed) return;
        PT_SLEEP(s, 500);
        servos_mover(servo_4, 4, 180, "basico-473");
        if (rb_failed) return;
        PT_SLEEP(s, 500);
        PT_YIELD(s);
    }
    PT_END(s);
}

void setup() { Serial.begin(115200); }

void loop() { rb_error_repeat(); proceso_1(); }
